    H, W = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(c for r in grid for c in r).most_common(1)[0][0]
    out = [r[:] for r in grid]
    for i, row in enumerate(grid):
        runs = []
        j = 0
        while j < W:
            if row[j] != bg:
                s = j
                while j < W and row[j] != bg:
                    j += 1
                runs.append((s, j - 1))
            else:
                j += 1
        if not runs:
            continue
        s, e = runs[-1]
        # detached short run at row end: check internal alternation (e.g. color,color should be color,bg)
        if s > 0 and e - s >= 1 and (e - s) < 3:
