def transform(grid):
    H, W = len(grid), len(grid[0])
    from collections import Counter
    cnt = Counter(c for r in grid for c in r)
    bg = cnt.most_common(1)[0][0]
    others = [c for c, _ in cnt.most_common() if c != bg]
    main = others[0] if others else bg
    out = [r[:] for r in grid]
    R = [i for i in range(H) if any(grid[i][j] == main for j in range(W))]
    if not R:
        return out
    cols = {}
    for j in range(W):
        S = [i for i in R if grid[i][j] == main]
        if S:
            cols[j] = S
    if not cols:
        return out
    kmax = max(len(S) for S in cols.values())
    for j, S in cols.items():
        if len(S) < kmax:
            Sset = set(S)
            for idx, i in enumerate(R):
                if i not in Sset and grid[i][j] == bg:
                    # only mark missing cells adjacent (in pattern-row order) to present ones
                    prev_in = idx > 0 and R[idx-1] in Sset
                    next_in = idx < len(R)-1 and R[idx+1] in Sset
                    if prev_in or next_in:
                        out[i][j] = 1
    return out
```

