    from collections import Counter
    cnt = Counter(c for r in grid for c in r)
    bg = cnt.most_common(1)[0][0]
    out = [r[:] for r in grid]
    colored = [i for i in range(H) if any(c != bg for c in grid[i])]
    if not colored:
        return out
    # template: row with the most non-bg cells (the complete copy)
    tmpl = max(colored, key=lambda i: sum(1 for c in grid[i] if c != bg))
    for i in colored:
        if i == tmpl:
            continue
        e = max(j for j in range(W) if grid[i][j] != bg)
        for j in range(W):
            if j > e and grid[i][j] == bg and grid[tmpl][j] != bg:
                out[i][j] = 1
            elif j < e and grid[i][j] == bg and grid[tmpl][j] != bg:
                out[i][j] = 1
    return out
